use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};

/// The shortest word counted, in bytes, until it is set.
pub const DEFAULT_MIN_LENGTH: usize = 1;

static MIN_LENGTH: AtomicUsize = AtomicUsize::new(DEFAULT_MIN_LENGTH);
static FOLD_CASE: AtomicBool = AtomicBool::new(true);

