/* wf_rs/htab.h - the module wf_rs::htab, ported to C (CodeCoreMorph, D-75): words and their
 * counts in a hash table with separate chaining. */
#ifndef WF_RS_HTAB_H
#define WF_RS_HTAB_H

#include <stddef.h>
#include <stdint.h>

/* What htab_add says. */
enum htab_status {
    HTAB_OK = 0,
    HTAB_ERANGE = 1, /* the count would go past UINT64_MAX: the old one stays */
    HTAB_ENOMEM = 2
};

/* A word and its count. The key is stored with a NUL after it, so its bytes can be handed out
 * as a C string; they stay where they are as long as the entry is in the table. */
typedef struct htab_entry {
    unsigned char *key; /* len bytes, then a NUL */
    size_t len;
    uint64_t count;
    struct htab_entry *next;
} htab_entry;

/* Words and their counts, in chains of buckets that double when they get long. */
typedef struct htab_table {
    htab_entry **buckets;
    size_t nbuckets;
    size_t size;
} htab_table;

/* Where a walk over a table is: start it zeroed. */
typedef struct htab_cursor {
    size_t bucket;
    const htab_entry *entry;
} htab_cursor;

/* FNV-1a, 32 bits wide. */
uint32_t htab_hash(const unsigned char *bytes, size_t len);

/* An empty table of nbuckets buckets, or NULL for none (or out of memory). htab_free frees
 * it, with its entries. */
htab_table *htab_new(size_t nbuckets);
void htab_free(htab_table *table);

/* How many different words it holds. */
size_t htab_size(const htab_table *table);

/* How many buckets it has now. */
size_t htab_buckets(const htab_table *table);

/* The entry of key, or NULL when it hasn't been counted. */
const htab_entry *htab_find(const htab_table *table, const unsigned char *key, size_t len);

/* The count of key: 0 when it isn't in the table. */
uint64_t htab_get(const htab_table *table, const unsigned char *key, size_t len);

/* Adds n to the count of key, which a new word starts at. */
enum htab_status htab_add(htab_table *table, const unsigned char *key, size_t len, uint64_t n);

/* The entry after the cursor's (the first for a zeroed cursor), or NULL after the last: every
 * entry once, in no particular order, as long as the table doesn't change. */
const htab_entry *htab_next(const htab_table *table, htab_cursor *cursor);

#endif /* WF_RS_HTAB_H */

/* The module wf_rs::htab, ported to C: words and their counts in a hash table with separate
 * chaining. */
#include "wf_rs/htab.h"

#include <stdlib.h>
#include <string.h>

/* A table grows past this many entries per bucket. */
#define LOAD 3

uint32_t htab_hash(const unsigned char *bytes, size_t len)
{
    uint32_t h = 2166136261u;
    size_t i;
    for (i = 0; i < len; i++) {
        h = (h ^ bytes[i]) * 16777619u;
    }
    return h;
}

htab_table *htab_new(size_t nbuckets)
{
    htab_table *table;
    if (nbuckets == 0) {
        return NULL;
    }
    table = malloc(sizeof *table);
    if (table == NULL) {
        return NULL;
    }
    table->buckets = calloc(nbuckets, sizeof *table->buckets);
    if (table->buckets == NULL) {
        free(table);
        return NULL;
    }
    table->nbuckets = nbuckets;
    table->size = 0;
    return table;
}

void htab_free(htab_table *table)
{
    size_t i;
    if (table == NULL) {
        return;
    }
    for (i = 0; i < table->nbuckets; i++) {
        htab_entry *entry = table->buckets[i];
        while (entry != NULL) {
            htab_entry *next = entry->next;
            free(entry->key);
            free(entry);
            entry = next;
        }
    }
    free(table->buckets);
    free(table);
}

size_t htab_size(const htab_table *table)
{
    return table->size;
}

size_t htab_buckets(const htab_table *table)
{
    return table->nbuckets;
}

static int same_key(const htab_entry *entry, const unsigned char *key, size_t len)
{
    return entry->len == len && (len == 0 || memcmp(entry->key, key, len) == 0);
}

static htab_entry *lookup(const htab_table *table, const unsigned char *key, size_t len)
{
    htab_entry *entry = table->buckets[htab_hash(key, len) % table->nbuckets];
    while (entry != NULL && !same_key(entry, key, len)) {
        entry = entry->next;
    }
    return entry;
}

const htab_entry *htab_find(const htab_table *table, const unsigned char *key, size_t len)
{
    return lookup(table, key, len);
}

uint64_t htab_get(const htab_table *table, const unsigned char *key, size_t len)
{
    const htab_entry *entry = lookup(table, key, len);
    return entry != NULL ? entry->count : 0;
}

/* Twice the buckets, every entry moved to its new one (the keys' bytes don't move). Out of
 * memory, the table keeps its buckets: longer chains, the same words. */
static void grow(htab_table *table)
{
    size_t n, i;
    htab_entry **buckets;
    if (table->nbuckets > SIZE_MAX / 2 / sizeof *buckets) {
        return;
    }
    n = table->nbuckets * 2;
    buckets = calloc(n, sizeof *buckets);
    if (buckets == NULL) {
        return;
    }
    for (i = 0; i < table->nbuckets; i++) {
        htab_entry *entry = table->buckets[i];
        while (entry != NULL) {
            htab_entry *next = entry->next;
            size_t slot = htab_hash(entry->key, entry->len) % n;
            entry->next = buckets[slot];
            buckets[slot] = entry;
            entry = next;
        }
    }
    free(table->buckets);
    table->buckets = buckets;
    table->nbuckets = n;
}

enum htab_status htab_add(htab_table *table, const unsigned char *key, size_t len, uint64_t n)
{
    htab_entry *entry = lookup(table, key, len);
    size_t slot;
    if (entry != NULL) {
        if (entry->count > UINT64_MAX - n) {
            return HTAB_ERANGE;
        }
        entry->count += n;
        return HTAB_OK;
    }
    if (len == SIZE_MAX) {
        return HTAB_ENOMEM;
    }
    entry = malloc(sizeof *entry);
    if (entry == NULL) {
        return HTAB_ENOMEM;
    }
    entry->key = malloc(len + 1);
    if (entry->key == NULL) {
        free(entry);
        return HTAB_ENOMEM;
    }
    if (len > 0) {
        memcpy(entry->key, key, len);
    }
    entry->key[len] = '\0';
    entry->len = len;
    entry->count = n;
    slot = htab_hash(key, len) % table->nbuckets;
    entry->next = table->buckets[slot];
    table->buckets[slot] = entry;
    table->size++;
    if (table->size / LOAD >= table->nbuckets && table->size > table->nbuckets * LOAD) {
        grow(table);
    }
    return HTAB_OK;
}

const htab_entry *htab_next(const htab_table *table, htab_cursor *cursor)
{
    size_t bucket;
    if (cursor->entry != NULL && cursor->entry->next != NULL) {
        cursor->entry = cursor->entry->next;
        return cursor->entry;
    }
    bucket = cursor->entry != NULL ? cursor->bucket + 1 : cursor->bucket;
    for (; bucket < table->nbuckets; bucket++) {
        if (table->buckets[bucket] != NULL) {
            cursor->bucket = bucket;
            cursor->entry = table->buckets[bucket];
            return cursor->entry;
        }
    }
    cursor->bucket = table->nbuckets;
    cursor->entry = NULL;
    return NULL;
}

