//! Ported from src/htab.c (CodeCoreMorph, D-68): words and their counts in a hash table with
//! separate chaining.

/// A table grows past this many entries per bucket.
const LOAD: usize = 3;

/// FNV-1a, 32 bits wide.
pub fn hash(bytes: &[u8]) -> u32 {
    bytes.iter().fold(2_166_136_261_u32, |h, &b| (h ^ u32::from(b)).wrapping_mul(16_777_619))
}

/// A word and its count. The key is stored with a NUL after it, so its bytes can be handed
/// out as a C string; they stay where they are as long as the entry is in the table.
#[derive(Debug)]
pub struct Entry {
    key: Box<[u8]>,
    count: u64,
}

impl Entry {
    /// The word.
    pub fn key(&self) -> &[u8] {
        &self.key[..self.key.len() - 1]
    }

    /// The word and a NUL.
    pub fn key_with_nul(&self) -> &[u8] {
        &self.key
    }

    /// How many times it was counted.
    pub fn count(&self) -> u64 {
        self.count
    }
}

/// A count would go past `u64::MAX`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Overflow;

/// Words and their counts, in chains of buckets that double when they get long.
#[derive(Debug)]
pub struct Table {
    buckets: Vec<Vec<Entry>>,
    size: usize,
}

impl Table {
    /// An empty table of `nbuckets` buckets, or `None` for none.
    pub fn with_buckets(nbuckets: usize) -> Option<Self> {
        if nbuckets == 0 {
            return None;
        }
        Some(Self { buckets: (0..nbuckets).map(|_| Vec::new()).collect(), size: 0 })
    }

    /// How many different words it holds.
    pub fn len(&self) -> usize {
        self.size
    }

    pub fn is_empty(&self) -> bool {
        self.size == 0
    }

    /// How many buckets it has now.
    pub fn buckets(&self) -> usize {
        self.buckets.len()
    }

    fn slot(&self, key: &[u8]) -> usize {
        hash(key) as usize % self.buckets.len()
    }

    /// The entry of `key`, if it has been counted.
    pub fn find(&self, key: &[u8]) -> Option<&Entry> {
        self.buckets[self.slot(key)].iter().find(|e| e.key() == key)
    }

    /// The count of `key`: 0 when it isn't in the table.
    pub fn get(&self, key: &[u8]) -> u64 {
        self.find(key).map_or(0, Entry::count)
    }

    /// Adds `n` to the count of `key`, which a new word starts at. A count that would overflow
    /// is refused, and the old one stays.
    pub fn add(&mut self, key: &[u8], n: u64) -> Result<(), Overflow> {
        let slot = self.slot(key);
        if let Some(entry) = self.buckets[slot].iter_mut().find(|e| e.key() == key) {
            entry.count = entry.count.checked_add(n).ok_or(Overflow)?;
            return Ok(());
        }
        let mut stored = Vec::with_capacity(key.len() + 1);
        stored.extend_from_slice(key);
        stored.push(0);
        self.buckets[slot].push(Entry { key: stored.into_boxed_slice(), count: n });
        self.size += 1;
        if self.size > self.buckets.len() * LOAD {
            self.grow();
        }
        Ok(())
    }

    /// Twice the buckets, every entry moved to its new one (the keys' bytes don't move).
    fn grow(&mut self) {
        let n = self.buckets.len() * 2;
        let mut buckets: Vec<Vec<Entry>> = (0..n).map(|_| Vec::new()).collect();
        for entry in self.buckets.drain(..).flatten() {
            buckets[hash(entry.key()) as usize % n].push(entry);
        }
        self.buckets = buckets;
    }

    /// Every entry once, in no particular order.
    pub fn iter(&self) -> impl Iterator<Item = &Entry> {
        self.buckets.iter().flatten()
    }
}

