use std::ffi::c_void;
use std::fmt;
use std::ptr::{self, NonNull};

/// bindgen's view of c/include/wf_rs/htab.h (written before each build; don't edit).
#[allow(non_camel_case_types, non_upper_case_globals, non_snake_case, dead_code, clippy::all)]
mod sys;

/// FNV-1a, 32 bits wide.
pub fn hash(bytes: &[u8]) -> u32 {
    // SAFETY: the C reads `bytes.len()` bytes at `bytes`.
    unsafe { sys::htab_hash(bytes.as_ptr(), bytes.len()) }
}

/// A word and its count. The key is stored with a NUL after it, so its bytes can be handed
/// out as a C string; they stay where they are as long as the entry is in the table.
#[repr(transparent)]
pub struct Entry(sys::htab_entry);

impl Entry {
    /// The entry a C `htab_entry *` points to (another module's view of the same struct).
    ///
    /// # Safety
    ///
    /// `raw` points to an entry of a table that outlives `'a` and doesn't change during it.
    pub(crate) unsafe fn from_raw<'a>(raw: *const c_void) -> &'a Entry {
        // SAFETY: Entry is the C entry, transparently; the caller vouches for the rest.
        unsafe { &*raw.cast::<Entry>() }
    }

    /// The word.
    pub fn key(&self) -> &[u8] {
        let with_nul = self.key_with_nul();
        &with_nul[..with_nul.len() - 1]
    }

    /// The word and a NUL.
    pub fn key_with_nul(&self) -> &[u8] {
        // SAFETY: the C keeps `len` bytes and a NUL at `key` while the entry is in its table,
        // which the borrow of the entry outlives.
        unsafe { std::slice::from_raw_parts(self.0.key, self.0.len + 1) }
    }

    /// How many times it was counted.
    pub fn count(&self) -> u64 {
        self.0.count
    }
}

impl fmt::Debug for Entry {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Entry")
            .field("key", &self.key_with_nul())
            .field("count", &self.count())
            .finish()
    }
}

/// A count would go past `u64::MAX`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Overflow;

/// Words and their counts, in chains of buckets that double when they get long.
pub struct Table {
    raw: NonNull<sys::htab_table>,
}

// SAFETY: the table owns its C memory alone, and the C keeps no state outside it.
unsafe impl Send for Table {}
// SAFETY: a shared table is only read.
unsafe impl Sync for Table {}

impl Table {
    /// An empty table of `nbuckets` buckets, or `None` for none.
    pub fn with_buckets(nbuckets: usize) -> Option<Self> {
        if nbuckets == 0 {
            return None;
        }
        // SAFETY: htab_new returns a new table, or NULL out of memory.
        let raw = unsafe { sys::htab_new(nbuckets) };
        Some(Self { raw: NonNull::new(raw).expect("out of memory") })
    }

    /// How many different words it holds.
    pub fn len(&self) -> usize {
        // SAFETY: the table is alive.
        unsafe { sys::htab_size(self.raw.as_ptr()) }
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// How many buckets it has now.
    pub fn buckets(&self) -> usize {
        // SAFETY: the table is alive.
        unsafe { sys::htab_buckets(self.raw.as_ptr()) }
    }

    /// The entry of `key`, if it has been counted.
    pub fn find(&self, key: &[u8]) -> Option<&Entry> {
        // SAFETY: the table is alive, and the C reads `key.len()` bytes at `key`.
        let found = unsafe { sys::htab_find(self.raw.as_ptr(), key.as_ptr(), key.len()) };
        // SAFETY: the entry is the table's, which the borrow of `self` keeps unchanged.
        (!found.is_null()).then(|| unsafe { Entry::from_raw(found.cast()) })
    }

    /// The count of `key`: 0 when it isn't in the table.
    pub fn get(&self, key: &[u8]) -> u64 {
        // SAFETY: the table is alive, and the C reads `key.len()` bytes at `key`.
        unsafe { sys::htab_get(self.raw.as_ptr(), key.as_ptr(), key.len()) }
    }

    /// Adds `n` to the count of `key`, which a new word starts at. A count that would overflow
    /// is refused, and the old one stays.
    pub fn add(&mut self, key: &[u8], n: u64) -> Result<(), Overflow> {
        // SAFETY: the table is alive, and the C copies `key.len()` bytes from `key`.
        match unsafe { sys::htab_add(self.raw.as_ptr(), key.as_ptr(), key.len(), n) } {
            sys::htab_status_HTAB_OK => Ok(()),
            sys::htab_status_HTAB_ERANGE => Err(Overflow),
            _ => panic!("out of memory"),
        }
    }

    /// Every entry once, in no particular order.
    pub fn iter(&self) -> impl Iterator<Item = &Entry> {
        let mut cursor = sys::htab_cursor { bucket: 0, entry: ptr::null() };
        std::iter::from_fn(move || {
            // SAFETY: the table is alive and, borrowed, doesn't change during the walk.
            let next = unsafe { sys::htab_next(self.raw.as_ptr(), &mut cursor) };
            // SAFETY: the entry is the table's, which the borrow of `self` keeps unchanged.
            (!next.is_null()).then(|| unsafe { Entry::from_raw(next.cast()) })
        })
    }
}

impl Drop for Table {
    fn drop(&mut self) {
        // SAFETY: the table is ours, and nothing borrows it any more.
        unsafe { sys::htab_free(self.raw.as_ptr()) }
    }
}

impl fmt::Debug for Table {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Table")
            .field("buckets", &self.buckets())
            .field("size", &self.len())
            .finish()
    }
}

/* wf_rs/sbuf.h - the module wf_rs::sbuf, ported to C (CodeCoreMorph, D-75): a growable byte
 * buffer. */
#ifndef WF_RS_SBUF_H
#define WF_RS_SBUF_H

#include <stddef.h>

/* The smallest capacity a buffer grows to. */
#define SBUF_MIN_CAPACITY 16

/* What the functions that grow a buffer say. */
enum sbuf_status {
    SBUF_OK = 0,
    SBUF_ERANGE = 1, /* no size_t is that large: the buffer stays as it was */
    SBUF_ENOMEM = 2
};

/* A growable byte buffer that grows by doubling from SBUF_MIN_CAPACITY, with a NUL after its
 * bytes once it has memory. A zeroed buffer is empty (sbuf_init makes one); sbuf_release
 * frees its memory. */
typedef struct sbuf {
    unsigned char *data;
    size_t len;
    size_t cap;
} sbuf;

/* The capacity a buffer of len bytes in cap needs for extra more and a NUL after them, in
 * *grown: 0 when it has room, else cap (or SBUF_MIN_CAPACITY) doubled until it does. */
enum sbuf_status sbuf_capacity_for(size_t len, size_t cap, size_t extra, size_t *grown);

/* An empty buffer, with no memory yet. */
void sbuf_init(sbuf *buf);

/* Appends n bytes. */
enum sbuf_status sbuf_append(sbuf *buf, const unsigned char *bytes, size_t n);

/* Appends one byte. */
enum sbuf_status sbuf_push(sbuf *buf, unsigned char c);

/* Empties the buffer and keeps its memory. */
void sbuf_clear(sbuf *buf);

/* Empties the buffer and gives its memory back. */
void sbuf_release(sbuf *buf);

#endif /* WF_RS_SBUF_H */

/* The module wf_rs::sbuf, ported to C: a growable byte buffer. */
#include "wf_rs/sbuf.h"

#include <stdint.h>
#include <stdlib.h>
#include <string.h>

enum sbuf_status sbuf_capacity_for(size_t len, size_t cap, size_t extra, size_t *grown)
{
    size_t wanted, n;
    *grown = 0;
    if (extra > SIZE_MAX - len || len + extra == SIZE_MAX) {
        return SBUF_ERANGE;
    }
    wanted = len + extra + 1;
    if (wanted <= cap) {
        return SBUF_OK;
    }
    n = cap == 0 ? SBUF_MIN_CAPACITY : cap;
    while (n < wanted) {
        if (n > SIZE_MAX / 2) {
            return SBUF_ERANGE;
        }
        n *= 2;
    }
