{
    return sbuf_append(buf, &c, 1);
}

void sbuf_clear(sbuf *buf)
{
    buf->len = 0;
    if (buf->data != NULL) {
        buf->data[0] = '\0';
    }
}

void sbuf_release(sbuf *buf)
