/// The capacity a buffer of `len` bytes in `cap` needs for `extra` more and a NUL after them:
/// `None` when it has room, else `cap` (or `MIN_CAPACITY`) doubled until it does.
pub fn capacity_for(len: usize, cap: usize, extra: usize) -> Result<Option<usize>, TooLarge> {
    let wanted = len.checked_add(extra).and_then(|n| n.checked_add(1)).ok_or(TooLarge)?;
    if wanted <= cap {
        return Ok(None);
    }
    let mut grown = if cap == 0 { MIN_CAPACITY } else { cap };
    while grown < wanted {
        grown = grown.checked_mul(2).ok_or(TooLarge)?;
    }
    Ok(Some(grown))
}

/// A growable byte buffer that grows as the C one did, by doubling from `MIN_CAPACITY`.
#[derive(Debug, Default, Clone, PartialEq, Eq)]
