    pub fn append(&mut self, s: &[u8]) -> Result<(), TooLarge> {
        if let Some(cap) = capacity_for(self.bytes.len(), self.bytes.capacity(), s.len())? {
            self.bytes.reserve_exact(cap - self.bytes.len());
        }
        self.bytes.extend_from_slice(s);
        Ok(())
    }

