#ifndef WF_RS_TOK_H
#define WF_RS_TOK_H

#include <stddef.h>

#include "wf_rs/sbuf.h"

/* What tok_next_word says. */
enum tok_status {
    TOK_END = 0,    /* the end of the text */
    TOK_WORD = 1,   /* the next word is in the buffer */
    TOK_ERANGE = 2, /* the word doesn't fit a buffer */
    TOK_ENOMEM = 3
};

/* The words of a text, one at a time. It reads the text, which outlives it. */
typedef struct tok {
    const unsigned char *text;
    size_t len;
    size_t pos;
} tok;

void tok_init(tok *tokens, const unsigned char *text, size_t len);

/* How many bytes of the text it has read. */
size_t tok_position(const tok *tokens);

/* The next word into word. A word too short to count is skipped (and stays in word when the
 * text ends after it). The settings are read once per call. */
enum tok_status tok_next_word(tok *tokens, sbuf *word);

#endif /* WF_RS_TOK_H */

