#include "wf_rs/tok.h"

#include <stdbool.h>

#include "wf_rs/conf.h"

/* ASCII only, as C's isalpha and isalnum are in the C locale, whatever the locale is. */
static bool is_letter(unsigned char c)
{
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

static bool is_word_char(unsigned char c)
{
    return is_letter(c) || (c >= '0' && c <= '9');
}

static unsigned char lower(unsigned char c)
{
    return c >= 'A' && c <= 'Z' ? (unsigned char)(c - 'A' + 'a') : c;
}

void tok_init(tok *tokens, const unsigned char *text, size_t len)
{
    tokens->text = text;
    tokens->len = len;
    tokens->pos = 0;
}

size_t tok_position(const tok *tokens)
{
    return tokens->pos;
}

enum tok_status tok_next_word(tok *tokens, sbuf *word)
{
    bool fold = conf_fold_case();
    size_t min = conf_min_length();
    const unsigned char *text = tokens->text;
    for (;;) {
        while (tokens->pos < tokens->len && !is_word_char(text[tokens->pos])) {
            tokens->pos++;
        }
        if (tokens->pos == tokens->len) {
            return TOK_END;
        }
        sbuf_clear(word);
        while (tokens->pos < tokens->len) {
            unsigned char c = text[tokens->pos];
            bool inside = c == '\'' && word->len > 0 && tokens->pos + 1 < tokens->len &&
                          is_letter(text[tokens->pos + 1]) && is_letter(word->data[word->len - 1]);
            enum sbuf_status status;
            if (!inside && !is_word_char(c)) {
                break;
            }
            status = sbuf_push(word, fold ? lower(c) : c);
            if (status == SBUF_ERANGE) {
                return TOK_ERANGE;
            }
            if (status != SBUF_OK) {
                return TOK_ENOMEM;
            }
            tokens->pos++;
        }
        if (word->len >= min) {
            return TOK_WORD;
        }
    }
}

