/// A letter or a digit (ASCII: C's `isalnum` in the C locale).
fn is_word_char(c: u8) -> bool {
    c.is_ascii_alphanumeric()
}

/// The words of a text, one at a time.
#[derive(Debug, Clone)]
pub struct Tokenizer<'a> {
    text: &'a [u8],
    pos: usize,
}

impl<'a> Tokenizer<'a> {
    pub fn new(text: &'a [u8]) -> Self {
        Self { text, pos: 0 }
    }

    /// How many bytes of the text it has read.
    pub fn position(&self) -> usize {
        self.pos
    }

    /// The next word into `word`: `Ok(true)`, or `Ok(false)` at the end of the text. A word
    /// too short to count is skipped (and stays in `word` when the text ends after it).
    pub fn next_word(&mut self, word: &mut Buffer) -> Result<bool, TooLarge> {
        let fold = conf::fold_case();
        let min = conf::min_length();
        loop {
            while self.pos < self.text.len() && !is_word_char(self.text[self.pos]) {
                self.pos += 1;
            }
            if self.pos == self.text.len() {
                return Ok(false);
