            word.clear();
            while self.pos < self.text.len() {
                let c = self.text[self.pos];
                let inside = c == b'\''
                    && !word.is_empty()
                    && self.text.get(self.pos + 1).is_some_and(u8::is_ascii_alphabetic)
                    && word.as_bytes().last().is_some_and(u8::is_ascii_alphabetic);
                if !inside && !is_word_char(c) {
                    break;
                }
                word.push(if fold { c.to_ascii_lowercase() } else { c })?;
                self.pos += 1;
            }
            if word.len() >= min {
                return Ok(true);
            }
        }
    }
}

