    htab_table *words;
};

wf_table *wf_table_new(void)
{
    wf_table *table = malloc(sizeof *table);
    if (table == NULL) {
        return NULL;
    }
    table->words = htab_new(WF_BUCKETS);
    if (table->words == NULL) {
        free(table);
        return NULL;
    }
    return table;
}

void wf_table_free(wf_table *table)
{
    if (table == NULL) {
        return;
    }
    htab_free(table->words);
    free(table);
}

enum wf_error wf_count_text(wf_table *table, const unsigned char *text, size_t len)
{
    tok tokens;
    sbuf word;
    enum wf_error error = WF_OK;
    tok_init(&tokens, text, len);
    sbuf_init(&word);
    for (;;) {
        enum tok_status found = tok_next_word(&tokens, &word);
        enum htab_status added;
        if (found == TOK_END) {
            break;
        }
        if (found != TOK_WORD) {
            error = found == TOK_ENOMEM ? WF_ENOMEM : WF_ERANGE;
            break;
        }
        added = htab_add(table->words, word.data, word.len, 1);
        if (added != HTAB_OK) {
            error = added == HTAB_ENOMEM ? WF_ENOMEM : WF_ERANGE;
            break;
        }
    }
    sbuf_release(&word);
    return error;
}

