{
    return htab_size(table->words);
}

uint64_t wf_lookup(const wf_table *table, const unsigned char *word, size_t len)
{
    return htab_get(table->words, word, len);
}

/* Most frequent first, then in byte order (a word before the longer ones it starts). */
static int by_count_then_text(const void *a, const void *b)
{
    const htab_entry *x = *(const htab_entry *const *)a;
    const htab_entry *y = *(const htab_entry *const *)b;
    size_t common = x->len < y->len ? x->len : y->len;
    int order;
    if (x->count != y->count) {
        return x->count > y->count ? -1 : 1;
    }
    order = common > 0 ? memcmp(x->key, y->key, common) : 0;
    if (order != 0) {
        return order;
    }
    return x->len < y->len ? -1 : x->len > y->len ? 1 : 0;
}

enum wf_error wf_top(const wf_table *table, size_t n, const htab_entry **out, size_t *found)
{
    size_t size = htab_size(table->words), i = 0;
    const htab_entry **all;
    htab_cursor cursor = {0, NULL};
    const htab_entry *entry;
    *found = 0;
    if (n == 0 || size == 0) {
        return WF_OK;
    }
    all = malloc(size * sizeof *all);
    if (all == NULL) {
        return WF_ENOMEM;
    }
    while (i < size && (entry = htab_next(table->words, &cursor)) != NULL) {
        all[i++] = entry;
    }
    qsort(all, i, sizeof *all, by_count_then_text);
    *found = n < i ? n : i;
    memcpy(out, all, *found * sizeof *all);
    free(all);
    return WF_OK;
}

const char *wf_strerror(enum wf_error error)
{
    switch (error) {
    case WF_OK:
        return "no error";
    case WF_ENOMEM:
        return "out of memory";
    case WF_EINVAL:
        return "invalid argument";
    case WF_ERANGE:
        return "count out of range";
    }
    return "unknown error";
}

