use std::ffi::CStr;
use std::fmt;
use std::ptr::NonNull;

use crate::htab;

/// bindgen's view of c/include/wf_rs/wf.h (written before each build; don't edit).
#[allow(non_camel_case_types, non_upper_case_globals, non_snake_case, dead_code, clippy::all)]
mod sys;

/// What went wrong, as the C interface's status codes say it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Error {
    /// Out of memory (the C interface's `WF_ENOMEM`).
    NoMemory,
    /// A bad argument (`WF_EINVAL`).
    InvalidArgument,
    /// A count would overflow (`WF_ERANGE`).
    Range,
}

impl Error {
    fn code(self) -> sys::wf_error {
        match self {
            Error::NoMemory => sys::wf_error_WF_ENOMEM,
            Error::InvalidArgument => sys::wf_error_WF_EINVAL,
            Error::Range => sys::wf_error_WF_ERANGE,
        }
    }

    /// The message the C interface gives for it.
    pub fn message(self) -> &'static str {
        // SAFETY: wf_strerror returns static, NUL-terminated text.
        let text = unsafe { CStr::from_ptr(sys::wf_strerror(self.code())) };
        text.to_str().expect("the messages are ASCII")
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.message())
    }
}

impl std::error::Error for Error {}

/// One counted word of a table.
#[derive(Debug, Clone, Copy)]
pub struct Word<'a> {
    entry: &'a htab::Entry,
}

impl<'a> Word<'a> {
    /// The word.
    pub fn text(&self) -> &'a [u8] {
        self.entry.key()
    }

    /// The word and a NUL, as the table keeps it.
    pub fn text_with_nul(&self) -> &'a [u8] {
        self.entry.key_with_nul()
    }

    /// How many times it was counted.
    pub fn count(&self) -> u64 {
        self.entry.count()
    }
}

/// A table of counted words.
pub struct Table {
    raw: NonNull<sys::wf_table>,
}

// SAFETY: the table owns its C memory alone, and the C keeps no state outside it.
unsafe impl Send for Table {}
// SAFETY: a shared table is only read.
unsafe impl Sync for Table {}

impl Default for Table {
    fn default() -> Self {
        Self::new()
    }
}

impl Table {
    /// An empty table.
    pub fn new() -> Self {
        // SAFETY: wf_table_new returns a new table, or NULL out of memory.
        let raw = unsafe { sys::wf_table_new() };
        Self { raw: NonNull::new(raw).expect("out of memory") }
    }

    /// Counts every word of `text` with the settings of `crate::conf`. On an error, the words
    /// before it stay counted.
    pub fn count_text(&mut self, text: &[u8]) -> Result<(), Error> {
        // SAFETY: the table is ours, and the C reads `text.len()` bytes at `text`.
        match unsafe { sys::wf_count_text(self.raw.as_ptr(), text.as_ptr(), text.len()) } {
            sys::wf_error_WF_OK => Ok(()),
            sys::wf_error_WF_ENOMEM => Err(Error::NoMemory),
            sys::wf_error_WF_EINVAL => Err(Error::InvalidArgument),
            _ => Err(Error::Range),
        }
    }

    /// How many different words it holds.
    pub fn len(&self) -> usize {
        // SAFETY: the table is alive.
        unsafe { sys::wf_table_size(self.raw.as_ptr()) }
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// How many times `word` was counted.
    pub fn lookup(&self, word: &[u8]) -> u64 {
        // SAFETY: the table is alive, and the C reads `word.len()` bytes at `word`.
        unsafe { sys::wf_lookup(self.raw.as_ptr(), word.as_ptr(), word.len()) }
    }

    /// The `n` most frequent words (fewer when the table holds fewer), most frequent first,
    /// ties in byte order.
    pub fn top(&self, n: usize) -> Vec<Word<'_>> {
        let wanted = n.min(self.len());
        let mut entries: Vec<*const sys::htab_entry> = Vec::with_capacity(wanted);
        let mut found = 0;
        // SAFETY: the table is alive, and `entries` has room for `wanted` pointers.
        let status =
            unsafe { sys::wf_top(self.raw.as_ptr(), wanted, entries.as_mut_ptr(), &mut found) };
        assert!(status == sys::wf_error_WF_OK, "out of memory");
        // SAFETY: the C wrote `found` (at most `wanted`) pointers.
        unsafe { entries.set_len(found) };
        entries
            .into_iter()
            // SAFETY: each entry is the table's, which the borrow of `self` keeps unchanged.
            .map(|entry| Word { entry: unsafe { htab::Entry::from_raw(entry.cast()) } })
            .collect()
    }
}

impl Drop for Table {
    fn drop(&mut self) {
        // SAFETY: the table is ours, and nothing borrows it any more.
        unsafe { sys::wf_table_free(self.raw.as_ptr()) }
    }
}

impl fmt::Debug for Table {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Table").field("len", &self.len()).finish()
    }
}

