/* The program wordfreq, ported to C: prints the most frequent words of its standard input. */
#include "wf_rs/wordfreq.h"

#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "wf_rs/conf.h"
#include "wf_rs/wf.h"

static int usage(void)
{
    fputs("usage: wordfreq [-k] [-m min] [count]\n", stderr);
    return 2;
}

static int fail(enum wf_error error)
{
    fprintf(stderr, "wordfreq: %s\n", wf_strerror(error));
    return 1;
}

/* C's atol, converted to size_t as the original program did: blanks, a sign, then the digits
 * up to the first other byte (0 without any); a negative number wraps. */
static size_t to_size(const char *arg)
{
    const unsigned char *p = (const unsigned char *)arg;
    uint64_t value = 0;
    int negative = 0;
    while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\v' || *p == '\f' || *p == '\r') {
        p++;
    }
    if (*p == '-' || *p == '+') {
        negative = *p == '-';
        p++;
    }
    for (; *p >= '0' && *p <= '9'; p++) {
        value = value * 10u + (uint64_t)(*p - '0');
    }
    return (size_t)(negative ? 0u - value : value);
}

/* All of a stream, or NULL out of memory. A read error ends the input, as fread's did. */
static unsigned char *read_all(FILE *in, size_t *len)
{
    size_t cap = 4096, n = 0, got;
    unsigned char *text = malloc(cap);
    if (text == NULL) {
        return NULL;
    }
    do {
        if (n == cap) {
            unsigned char *bigger = cap <= SIZE_MAX / 2 ? realloc(text, cap * 2) : NULL;
            if (bigger == NULL) {
                free(text);
                return NULL;
            }
            text = bigger;
            cap *= 2;
        }
        got = fread(text + n, 1, cap - n, in);
        n += got;
    } while (got > 0);
    *len = n;
    return text;
}

int wf_rs_wordfreq_main(int argc, char **argv)
{
    size_t count = 10, len = 0, found = 0, i;
    unsigned char *text;
    wf_table *table;
    const htab_entry **top;
    enum wf_error error;
    int arg;
    for (arg = 1; arg < argc; arg++) {
        if (strcmp(argv[arg], "-k") == 0) {
            conf_set_fold_case(false);
        } else if (strcmp(argv[arg], "-m") == 0) {
            if (++arg >= argc) {
                return usage();
            }
            conf_set_min_length(to_size(argv[arg]));
        } else if (argv[arg][0] == '-') {
            return usage();
        } else {
            count = to_size(argv[arg]);
        }
    }
    text = read_all(stdin, &len);
    if (text == NULL) {
        return fail(WF_ENOMEM);
    }
    table = wf_table_new();
    if (table == NULL) {
        free(text);
        return fail(WF_ENOMEM);
    }
    error = wf_count_text(table, text, len);
    free(text);
    if (error != WF_OK) {
        wf_table_free(table);
        return fail(error);
    }
    if (count > wf_table_size(table)) {
        count = wf_table_size(table);
    }
    top = malloc((count > 0 ? count : 1) * sizeof *top);
    error = top != NULL ? wf_top(table, count, top, &found) : WF_ENOMEM;
    if (error != WF_OK) {
        free(top);
        wf_table_free(table);
        return fail(error);
    }
    /* Like printf's, a failed write doesn't change the exit status. */
    for (i = 0; i < found; i++) {
        printf("%7" PRIu64 " ", top[i]->count);
        fwrite(top[i]->key, 1, top[i]->len, stdout);
        putchar('\n');
    }
    fflush(stdout);
    free(top);
    wf_table_free(table);
    return 0;
}

