//! Ported from tools/wordfreq.c (CodeCoreMorph, D-68): prints the most frequent words of its
//! standard input.
//!
//! usage: wordfreq [-k] [-m min] [count]
//!   -k      keep case (by default words are folded to lower case)
//!   -m min  skip words shorter than min
//!   count   how many words to print (default 10)
#![forbid(unsafe_code)]

use std::io::{self, Read, Write};
use std::process::ExitCode;

use wf_rs::conf;
use wf_rs::wf::{Table, Word};

fn usage() -> ExitCode {
    eprintln!("usage: wordfreq [-k] [-m min] [count]");
    ExitCode::from(2)
}

/// C's `atol`, converted to `size_t` as the C did: blanks, a sign, then the digits up to the
/// first other byte (0 without any); a negative number wraps.
fn atol(arg: &[u8]) -> usize {
    let mut rest = arg
        .iter()
        .copied()
        .skip_while(|c| matches!(c, b' ' | b'\t' | b'\n' | b'\x0b' | b'\x0c' | b'\r'))
        .peekable();
    let negative = match rest.peek() {
        Some(b'-') => {
            rest.next();
            true
        }
        Some(b'+') => {
            rest.next();
            false
        }
        _ => false,
    };
    let mut value: i64 = 0;
    for c in rest.take_while(u8::is_ascii_digit) {
        value = value.wrapping_mul(10).wrapping_add(i64::from(c - b'0'));
    }
    (if negative { value.wrapping_neg() } else { value }) as usize
}

/// Each word as `%7lu %s` would print it.
fn print(words: &[Word<'_>]) -> io::Result<()> {
    let mut out = io::stdout().lock();
    for word in words {
        write!(out, "{:>7} ", word.count())?;
        out.write_all(word.text())?;
        out.write_all(b"\n")?;
    }
    out.flush()
}

fn main() -> ExitCode {
    let mut count = 10;
    let mut args = std::env::args_os().skip(1);
    while let Some(arg) = args.next() {
        let arg = arg.as_encoded_bytes();
        if arg == b"-k" {
            conf::set_fold_case(false);
        } else if arg == b"-m" {
            let Some(min) = args.next() else {
                return usage();
            };
            conf::set_min_length(atol(min.as_encoded_bytes()));
        } else if arg.first() == Some(&b'-') {
            return usage();
        } else {
            count = atol(arg);
        }
    }

    // Read errors end the input, as fread's did.
    let mut text = Vec::new();
    io::stdin().lock().read_to_end(&mut text).ok();
    let mut table = Table::new();
    if let Err(error) = table.count_text(&text) {
        eprintln!("wordfreq: {error}");
        return ExitCode::from(1);
    }
    // Like printf's, a failed write doesn't change the exit status.
    print(&table.top(count)).ok();
    ExitCode::SUCCESS
}

