/* The tests of tests/test_tok.rs, translated from Rust (CodeCoreMorph, D-75): one case per
 * Rust test, each a CTest test of the same name. The settings are global, so each case sets
 * the ones it needs. */
#include "codecoremorph_tap.h"

#include <stdbool.h>
#include <string.h>

#include "wf_rs/conf.h"
#include "wf_rs/sbuf.h"
#include "wf_rs/tok.h"

static void settings(bool fold, size_t min)
{
    conf_set_fold_case(fold);
    conf_set_min_length(min);
}

/* The words of text, joined by "|", into out (room for size bytes). */
static const char *words(const char *text, char *out, size_t size)
{
    tok tokens;
    sbuf word;
    size_t used = 0;
    out[0] = '\0';
    tok_init(&tokens, (const unsigned char *)text, strlen(text));
    sbuf_init(&word);
    while (tok_next_word(&tokens, &word) == TOK_WORD) {
        size_t need = word.len + (used > 0);
        if (used + need + 1 > size) {
            break;
        }
        if (used > 0) {
            out[used++] = '|';
        }
        memcpy(out + used, word.data, word.len);
        used += word.len;
        out[used] = '\0';
    }
    sbuf_release(&word);
    return out;
}

static void words_are_split_at_punctuation_and_folded(void)
{
    char out[64];
    settings(true, 1);
    CCM_CHECK_STR(words("The cat, the HAT.", out, sizeof out), "the|cat|the|hat");
}

static void blank_text_has_no_words(void)
{
