}

static void digits_are_word_characters(void)
{
    char out[64];
    settings(true, 1);
    CCM_CHECK_STR(words("route 66, 3rd", out, sizeof out), "route|66|3rd");
}

static void case_is_kept_when_folding_is_off(void)
