#include "wf_rs/wf.h"

static const char TEXT[] = "b a c b a b, A! c d";

static enum wf_error count(wf_table *table, const char *text)
{
    return wf_count_text(table, (const unsigned char *)text, strlen(text));
}

static uint64_t lookup(const wf_table *table, const char *word)
{
    return wf_lookup(table, (const unsigned char *)word, strlen(word));
}

/* A table of TEXT's words, with the default settings (NULL out of memory). */
static wf_table *counted(void)
{
    wf_table *table;
    conf_set_fold_case(true);
    conf_set_min_length(1);
    table = wf_table_new();
    if (table != NULL && count(table, TEXT) != WF_OK) {
        wf_table_free(table);
        return NULL;
    }
    return table;
}

/* The word of an entry as a C string (the table keeps a NUL after it). */
static const char *word(const htab_entry *entry)
{
    return (const char *)entry->key;
}

static void a_new_table_is_empty(void)
{
    wf_table *table = wf_table_new();
    CCM_CHECK(table != NULL);
    if (table != NULL) {
        CCM_CHECK_UINT(wf_table_size(table), 0);
    }
    wf_table_free(table);
}

static void counting_succeeds(void)
{
