    conf_set_fold_case(true);
    conf_set_min_length(1);
    CCM_CHECK(table != NULL);
    if (table != NULL) {
        CCM_CHECK_INT(count(table, TEXT), WF_OK);
    }
    wf_table_free(table);
}

static void four_different_words(void)
{
    wf_table *table = counted();
    CCM_CHECK(table != NULL);
    if (table != NULL) {
        CCM_CHECK_UINT(wf_table_size(table), 4);
    }
    wf_table_free(table);
}

static void lookup_counts_folded_words(void)
{
    wf_table *table = counted();
    CCM_CHECK(table != NULL);
    if (table != NULL) {
        CCM_CHECK_UINT(lookup(table, "a"), 3);
        CCM_CHECK_UINT(lookup(table, "b"), 3);
        CCM_CHECK_UINT(lookup(table, "z"), 0);
    }
    wf_table_free(table);
}

