    if (table != NULL && wf_top(table, 3, top, &found) == WF_OK && found == 3) {
        CCM_CHECK_STR(word(top[0]), "a");
        CCM_CHECK_UINT(top[0]->count, 3);
        CCM_CHECK_STR(word(top[1]), "b");
