/* The tests of tests/cli.rs, translated from Rust (CodeCoreMorph, D-75): the wordfreq program,
 * run as a user would, its output compared with tests/sample.out and tests/sample-k.out. CMake
 * defines where the program and the data are (CCM_BINARY_DIR, CCM_SOURCE_DIR). POSIX: popen
 * and the shell's redirections. */
#define _POSIX_C_SOURCE 200809L

#include "codecoremorph_tap.h"

#include <stdlib.h>
#include <string.h>
#include <sys/wait.h>

#define PROGRAM CCM_BINARY_DIR "/c/wordfreq"
#define DATA CCM_SOURCE_DIR "/tests/"

struct run {
    char out[8192];
    int status;
};

/* All of a data file, as a C string, into buf (empty when it can't be read). */
static const char *data(const char *name, char *buf, size_t size)
{
    char path[1024];
    size_t n = 0;
    FILE *file;
    snprintf(path, sizeof path, "%s%s", DATA, name);
    file = fopen(path, "rb");
    if (file != NULL) {
        n = fread(buf, 1, size - 1, file);
        fclose(file);
    }
    buf[n] = '\0';
    return buf;
}

/* The program's output and exit status, run with args (quoted for the shell) on a data file
 * (NULL: no input). */
static void run(const char *args, const char *input, struct run *r)
{
    char command[2048], path[1024];
    size_t n = 0;
    FILE *out;
    r->status = -1;
    snprintf(path, sizeof path, "%s%s", input != NULL ? DATA : "/dev/null",
             input != NULL ? input : "");
    snprintf(command, sizeof command, "'%s' %s <'%s' 2>/dev/null", PROGRAM, args, path);
    out = popen(command, "r");
    if (out != NULL) {
        int status;
        n = fread(r->out, 1, sizeof r->out - 1, out);
        status = pclose(out);
        r->status = WIFEXITED(status) ? WEXITSTATUS(status) : -1;
    }
    r->out[n] = '\0';
}

static void the_three_most_frequent_words(void)
{
    static struct run r;
    static char expected[8192];
    run("3", "sample.txt", &r);
    CCM_CHECK_INT(r.status, 0);
    CCM_CHECK_STR(r.out, data("sample.out", expected, sizeof expected));
}

static void case_kept_and_short_words_skipped(void)
{
    static struct run r;
    static char expected[8192];
    run("-k -m 4 2", "sample.txt", &r);
    CCM_CHECK_INT(r.status, 0);
    CCM_CHECK_STR(r.out, data("sample-k.out", expected, sizeof expected));
}

static void an_unknown_option_shows_the_usage(void)
{
    static struct run r;
    run("-x", NULL, &r);
    CCM_CHECK_INT(r.status, 2);
    CCM_CHECK_STR(r.out, "");
}

int main(int argc, char **argv)
{
    CCM_SELECT(argc, argv);
    CCM_RUN(the_three_most_frequent_words);
    CCM_RUN(case_kept_and_short_words_skipped);
    CCM_RUN(an_unknown_option_shows_the_usage);
    return ccm_done();
}
